Rules.InvariantScript:
Set(glbDayStart, DateAdd(DateValue(Text(glbSelectedDate, "yyyy-mm-dd")), 8 * 60, TimeUnit.Minutes));
Set(glbDayEnd, DateAdd(DateValue(Text(glbSelectedDate, "yyyy-mm-dd")), 18 * 60, TimeUnit.Minutes));
UpdateContext({varShowTimeline: false});

NotificationType.Success;
ClearCollect(colRoomBookings,
    Sort(
        Filter(
            Book_Bookings,
            RoomID.Value = varSelectedRoom.RoomID,
            StartDateTime >= Timeline_DayStart,
            EndDateTime <= Timeline_DayEnd
        ),
        StartDateTime,
        SortOrder.Ascending
    )
);
Clear(colTimelineRows);
ForAll(
    colRoomBookings As booking,
    Collect(colTimelineRows, {
        RowType: "booked",
        RowStart: booking.StartDateTime,
        RowEnd: booking.EndDateTime,
        RowHeight: DateDiff(booking.StartDateTime, booking.EndDateTime, TimeUnit.Minutes) / 60 * 120,
        Title: booking.Title,
        BookedBy: booking.BookedBy.DisplayName
    })
);
Clear(colTimelineRows);
ForAll(
    colRoomBookings As booking,
    Collect(colTimelineRows, {
        RowType: "booked",
        RowStart: booking.StartDateTime,
        RowEnd: booking.EndDateTime,
        RowHeight: DateDiff(booking.StartDateTime, booking.EndDateTime, TimeUnit.Minutes) / 60 * 120,
        Title: booking.Title,
        BookedBy: booking.BookedBy.DisplayName
    })
);
Set(varBookingsLoaded, true);
If(varBookingsLoaded,
    If(
        IsEmpty(colRoomBookings),
        Collect(colTimelineRows, {
            RowType: "free",
            RowStart: Timeline_DayStart,
            RowEnd: Timeline_DayEnd,
            RowHeight: DateDiff(Timeline_DayStart, Timeline_DayEnd, TimeUnit.Minutes) / 60 * 120,
            Title: "",
            BookedBy: ""
        }),
        // Free slot before first booking
        If(
            First(colRoomBookings).StartDateTime > Timeline_DayStart,
            Collect(colTimelineRows, {
                RowType: "free",
                RowStart: Timeline_DayStart,
                RowEnd: First(colRoomBookings).StartDateTime,
                RowHeight: DateDiff(Timeline_DayStart, First(colRoomBookings).StartDateTime, TimeUnit.Minutes) / 60 * 120,
                Title: "",
                BookedBy: ""
            })
        );
        ForAll(
            colRoomBookings As booking,
            With(
                {
                    nextBooking: LookUp(
                        colRoomBookings,
                        StartDateTime > booking.EndDateTime,
                        StartDateTime
                    )
                },
                If(
                    IsBlank(nextBooking) && booking.EndDateTime < Timeline_DayEnd,
                    Collect(colTimelineRows, {
                        RowType: "free",
                        RowStart: booking.EndDateTime,
                        RowEnd: Timeline_DayEnd,
                        RowHeight: DateDiff(booking.EndDateTime, Timeline_DayEnd, TimeUnit.Minutes) / 60 * 120,
                        Title: "",
                        BookedBy: ""
                    }),
                    !IsBlank(nextBooking),
                    Collect(colTimelineRows, {
                        RowType: "free",
                        RowStart: booking.EndDateTime,
                        RowEnd: nextBooking,
                        RowHeight: DateDiff(booking.EndDateTime, nextBooking, TimeUnit.Minutes) / 60 * 120,
                        Title: "",
                        BookedBy: ""
                    })
                )
            )
        )
    )
);
ClearCollect(colTimelineRows, Sort(colTimelineRows, RowStart, SortOrder.Ascending))

